        require(_user != address(0),"Invalid address");

        vip[_user] = false;
    }

    function ownerBouns(address _user) external onlyOwner {
        if(scores[_user] > 0) {
            if(scores[_user] >= 80) {
                if(!blacklisted[_user]) {
                    scores[_user] = scores[_user] + 20;
                }
            }
        } 
    }
}

